    "help": {
      "prompt": "Answer in your own words, or use this reply.",
      "answers": [
        "Sure, I have a few minutes. I’m a Christian myself."
      ]
    }
  },
  "topics": [
    {
      "id": "word-mormon",
      "title": "The word Mormon",
      "summary": "Lesson question 1.",
      "background": "Read the lesson question as written. Your partner gives the lesson answer.",
      "question": {
        "id": "word-mormon",
        "text": "Why is the use or non-use of the word Mormon a good thing to bring up with your Mormon friend?",
        "caption": "Lesson 1 · Question 1",
        "help": {
          "hint": "Try answering from the lesson first. Tap Suggested responses to see the lesson answer.",
          "answers": [
            "Because the Mormon church ran the “I’m a Mormon” campaign, and then in 2018 President Nelson taught that to remove the Lord’s name from the Lord’s Church is “a major victory for Satan.”"
          ]
        }
      },
      "followUps": []
    },
    {
      "id": "first-vision-accounts",
      "title": "First Vision accounts",
      "summary": "Lesson question 2.",
      "background": "Read the lesson question as written. Your partner gives the lesson answer.",
      "question": {
        "id": "first-vision-accounts",
        "text": "How many different first vision accounts does the LDS church recognize and how do they defend the differing accounts?",
        "caption": "Lesson 1 · Question 2",
        "help": {
          "hint": "Try answering from the lesson first. Tap Suggested responses to see the lesson answer.",
          "answers": [
            "There are nine different documented first vision accounts. Many Mormons will say that the differing accounts can be harmonized, similar to how the four gospels are harmonized."
          ]
        }
      },
      "followUps": []
    },
    {
      "id": "expected-response",
      "title": "The expected response",
      "summary": "Lesson question 3.",
      "background": "Read the lesson question as written. Your partner gives the lesson answer.",
      "question": {
        "id": "expected-response",
        "text": "Suppose you were to share with your Mormon friend that there were multiple first vision accounts. What kind of response should you expect from a Mormon regarding the multiple first vision accounts?",
        "caption": "Lesson 1 · Question 3",
        "help": {
          "hint": "Try answering from the lesson first. Tap Suggested responses to see the lesson answer.",
          "answers": [
            "The most common response will be likened to the idea that there is a harmony to be found within the accounts."
          ]
        }
      },
      "followUps": []
    },
    {
      "id": "best-rejoinder",
      "title": "The best rejoinder",
      "summary": "Lesson question 4.",
      "background": "Read the lesson question as written. Your partner gives the lesson answer.",
      "question": {
        "id": "best-rejoinder",
        "text": "Given the “typical” response to multiple versions, what would be the best rejoinder?",
        "caption": "Lesson 1 · Question 4",
        "help": {
          "hint": "Try answering from the lesson first. Tap Suggested responses to see the lesson answer.",
          "answers": [
            "Use a question to help move your point. For example, you could ask, “Have you ever considered that the accounts present Joseph at different ages?” “Is it possible there were multiple first visions?” This is obviously making the point that if there were multiple “first visions,” then there was really only one first vision, and subsequent visions would be considered another vision; but that is not what the LDS church teaches. You may have to work this out with them and guide them into discovering the problem for themselves."
          ]
        }
      },
      "followUps": []
    },
